def sanitize(event):
    result = {}
    if not isinstance(event, dict):
        return result

    for key in ("operation", "status"):
        value = event.get(key)
        if isinstance(value, str) and len(value) <= 256 and all(ord(char) >= 32 for char in value):
            result[key] = value

    value = event.get("estimated_tokens")
    if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
        result["estimated_tokens"] = value

    return result
